import("stdfaust.lib");
gain = hslider("Gain [unit:dB]", 0, -60, 12, 0.1) : ba.db2linear : si.smoo;
process = _ * gain, _ * gain;

import("stdfaust.lib");
cutoff = hslider("Cutoff [unit:Hz]", 1000, 20, 20000, 1) : si.smoo;
q = hslider("Resonance Q", 1.0, 0.5, 10, 0.01) : si.smoo;
drive = hslider("Drive", 0.2, 0, 1, 0.01) : si.smoo;
filter = fi.resonlp(cutoff, q, 1.0) : fi.resonlp(cutoff, q, 1.0);
channel(x) = x : filter : ef.cubicnl(drive, 0);
process = channel, channel;

import("stdfaust.lib");
process = par(i, 2, hs) with {
    cutoff = hslider("Cutoff [unit:Hz]", 8000, 1000, 20000, 1) : si.smoo;
    gain   = hslider("Shelf Gain [unit:dB]", 6, -12, 12, 0.1) : si.smoo;
    hs = fi.highshelf(2, gain, cutoff);
};

import("stdfaust.lib");
MAXD = 192000;
dtime = hslider("Delay Time [unit:ms]", 350, 1, 2000, 1) : si.smoo
        : *(ma.SR/1000.0) : min(MAXD-1) : max(1);
fb    = hslider("Feedback [unit:%]", 0.5, 0, 0.95, 0.01) : si.smoo;
mix   = hslider("Dry/Wet", 0.5, 0, 1, 0.01) : si.smoo;
echoCh(x) = x * (1 - mix) + (x : (+ : de.fdelay(MAXD, dtime)) ~ *(fb)) * mix;
process = echoCh, echoCh;

import("stdfaust.lib");
rate = hslider("Rate [unit:Hz]", 0.5, 0.01, 5, 0.01) : si.smoo;
depth = hslider("Depth", 0.2, 0, 1, 0.01) : si.smoo;
mix = hslider("Mix", 0.3, 0, 1, 0.01) : si.smoo;
maxDel = 4096;
lfo(f) = os.lf_triangle(f) * 0.5 + 0.5;
voice(f, x) = de.fdelay(maxDel, (10.0 + 20.0 * depth * lfo(f)) * ma.SR * 0.001, x);
chorusCh(f, x) = x * (1 - mix) + voice(f, x) * mix;
process = chorusCh(rate), chorusCh(rate * 1.13);

import("stdfaust.lib");
drywet = hslider("Dry/Wet [unit:%]", 0.8, 0, 1, 0.01) : si.smoo;
ratio  = hslider("Ratio", 4, 1, 10, 0.1) : si.smoo;
thresh = hslider("Threshold [unit:dB]", -12, -60, 0, 0.1) : si.smoo;
attMs  = hslider("Attack [unit:ms]", 10, 1, 100, 1) : si.smoo;
relMs  = hslider("Release [unit:ms]", 100, 10, 500, 1) : si.smoo;
attSec = attMs : *(0.001);
relSec = relMs : *(0.001);
comp   = co.compressor_stereo(ratio, thresh, attSec, relSec);
process = _,_ : ef.dryWetMixer(drywet, comp);

import("stdfaust.lib");
hpCut = hslider("HP Cut [unit:Hz]", 30, 20, 200, 1) : si.smoo;
hp = fi.highpass(2, hpCut);
lsFreq = hslider("Low Shelf Freq [unit:Hz]", 120, 40, 500, 1) : si.smoo;
lsGain = hslider("Low Shelf Gain [unit:dB]", 6, -12, 12, 0.1) : ba.db2linear : si.smoo;
ls = fi.lowshelf(2, lsGain, lsFreq);
hsFreq = hslider("High Shelf Freq [unit:Hz]", 8000, 2000, 20000, 1) : si.smoo;
hsGain = hslider("High Shelf Gain [unit:dB]", -3, -12, 0, 0.1) : ba.db2linear : si.smoo;
hs = fi.highshelf(2, hsGain, hsFreq);
drive = hslider("Saturation Drive", 0.5, 0, 1, 0.01) : si.smoo;
sat = ef.cubicnl(drive, 0);
compRatio = hslider("Comp Ratio", 4, 1, 10, 0.1) : si.smoo;
compThresh = hslider("Comp Thresh [unit:dB]", -20, -60, 0, 0.1) : si.smoo;
compAtt = hslider("Comp Attack [unit:ms]", 5, 0.1, 100, 0.1) : si.smoo;
compRel = hslider("Comp Release [unit:ms]", 50, 10, 500, 1) : si.smoo;
compMix = hslider("Comp Mix", 0.5, 0, 1, 0.01) : si.smoo;
comp = ef.dryWetMixer(compMix, co.compressor_stereo(compRatio, compThresh, compAtt, compRel));
fb1 = hslider("Reverb FB1", 0.7, 0, 0.99, 0.01) : si.smoo;
fb2 = hslider("Reverb FB2", 0.7, 0, 0.99, 0.01) : si.smoo;
damp = hslider("Reverb Damp", 0.5, 0, 1, 0.01) : si.smoo;
revMix = hslider("Reverb Mix", 0.3, 0, 1, 0.01) : si.smoo;
rev = re.stereo_freeverb(fb1, fb2, damp, 30);
revWet = ef.dryWetMixer(revMix, rev);
process = _,_ <: hp, hp :> _,_ <: ls, ls :> _,_ <: hs, hs :> _,_ <: sat, sat :> _,_ <: comp, comp :> _,_ <: revWet, revWet :> _,_;

import("stdfaust.lib");
ratio  = hslider("Ratio", 4, 1, 20, 0.1) : si.smoo;
thresh = hslider("Threshold [unit:dB]", -20, -60, 0, 0.1) : si.smoo;
att    = hslider("Attack [unit:ms]", 10, 0.1, 200, 0.1) : si.smoo : *(0.001);
rel    = hslider("Release [unit:ms]", 100, 10, 1000, 1) : si.smoo : *(0.001);
process = co.compressor_stereo(ratio, thresh, att, rel, _, _);

import("stdfaust.lib");
threshold = hslider("Threshold [unit:dB]", -30, -60, 0, 0.1) : si.smoo;
ratio = hslider("Ratio", 4, 1, 20, 0.1) : si.smoo;
attack = hslider("Attack [unit:ms]", 10, 0.1, 100, 0.1) : si.smoo : *(ma.SR/1000.0);
release = hslider("Release [unit:ms]", 100, 10, 1000, 1) : si.smoo : *(ma.SR/1000.0);
makeup = hslider("Makeup Gain [unit:dB]", 0, -20, 20, 0.1) : ba.db2linear : si.smoo;
process = _,_ : co.compressor_stereo(ratio, threshold, attack, release, _, _) * makeup;

import("stdfaust.lib");
ratio   = hslider("Ratio", 4, 1, 20, 0.1) : si.smoo;
thresh  = hslider("Threshold [unit:dB]", -20, -60, 0, 0.1) : si.smoo;
att     = hslider("Attack [unit:ms]", 10, 0.1, 200, 0.1) : si.smoo;
rel     = hslider("Release [unit:ms]", 100, 10, 500, 1) : si.smoo;
makeup  = hslider("Makeup Gain [unit:dB]", 0, -12, 12, 0.1) : ba.db2linear : si.smoo;
process = _,_ : co.compressor_stereo(ratio, thresh, att, rel) : * makeup;

import("stdfaust.lib");
process = par(i,2,saw) with {
    freq = hslider("Freq [unit:Hz]", 440, 20, 20000, 1) : si.smoo;
    attackMs = hslider("Attack [unit:ms]", 10, 1, 5000, 1) : si.smoo;
    decayMs = hslider("Decay [unit:ms]", 100, 1, 5000, 1) : si.smoo;
    sustain = hslider("Sustain", 0.7, 0, 1, 0.01) : si.smoo;
    releaseMs = hslider("Release [unit:ms]", 200, 1, 5000, 1) : si.smoo;
    gate = hslider("Gate", 0, 0, 1, 1);
    at = attackMs * 0.001;
    dt = decayMs * 0.001;
    rt = releaseMs * 0.001;
    env = en.adsr(at, dt, sustain, rt, gate);
    saw = os.sawtooth(freq) * env;
};
